// Function to unlock scroll on modal close
function unlockScroll() {
  document.body.classList.remove("modal-open");
  document.body.style.overflow = ""; // Reset overflow
}

// Call functions to create the modal and navbar
createNavbar();
createModal();

function showThankYouMessage() {
  const thankYouMessage = document.createElement("p");
  thankYouMessage.id = "thank-you";
  thankYouMessage.textContent = "Thank you for your submission!";
  thankYouMessage.style.display = "inline";
  thankYouMessage.style.color = "green";

  document.getElementById("tryNowForm").appendChild(thankYouMessage);

  setTimeout(function () {
    const modal = bootstrap.Modal.getInstance(
      document.getElementById("tryNowModal")
    );
    modal.hide();
    thankYouMessage.remove(); // Remove the message after hiding modal
  }, 3000);
}

// Handle form submission
document.getElementById("tryNowForm").addEventListener("submit", function (e) {
  e.preventDefault(); // Prevent default form submission

  const submitButton = this.querySelector("button[type='submit']");
  submitButton.textContent = "Sending . . .";
  submitButton.disabled = true;

  // Data to be sent to the Google Apps Script URL
  const scriptURL =
    "https://script.google.com/macros/s/AKfycbwBZ8oBmbo0qczs4vfFu9DHgBeCLJZPVW99Rit_ETx4YJSlThf0QKFJ0Phympb2DHlf7Q/exec";
  const formData = new FormData(this);

  fetch(scriptURL, { method: "POST", body: formData })
    .then((response) => {
      showThankYouMessage();
      this.reset(); // Reset the form
    })
    .catch((error) => {
      alert("There was an error submitting the form.");
      console.error("Error!", error.message);
    })
    .finally(() => {
      submitButton.textContent = "Submit";
      submitButton.disabled = false;
    });
});
// Function to unlock scroll on modal close
function unlockScroll() {
  document.body.classList.remove("modal-open");
  document.body.style.overflow = ""; // Reset overflow
}

// Attach the unlockScroll function to the modal close event
document
  .getElementById("tryNowModal")
  .addEventListener("hidden.bs.modal", unlockScroll);
setTimeout(function () {
  const modal = bootstrap.Modal.getInstance(
    document.getElementById("tryNowModal")
  );
  if (modal) {
    modal.hide();
  } else {
    console.warn(
      "Modal instance not found. Ensure Bootstrap JavaScript is loaded correctly."
    );
  }
  thankYouMessage.remove(); // Remove the thank-you message
}, 3000);
function setupDropdown() {
  const dropdownToggle = document.getElementById("customDropdown");
  const dropdownMenu = document.getElementById("customDropdownMenu");
  const dropdownItems = document.querySelectorAll(".custom-dropdown-item");

  // Toggle dropdown menu
  dropdownToggle.addEventListener("click", (e) => {
    e.stopPropagation();
    dropdownMenu.classList.toggle("show");
  });

  // Handle item selection
  dropdownItems.forEach((item) => {
    item.addEventListener("click", (e) => {
      e.stopPropagation();
      dropdownToggle.querySelector("span").textContent = item.textContent;
      dropdownMenu.classList.remove("show");
    });
  });

  // Close dropdown when clicking outside
  document.addEventListener("click", () => {
    dropdownMenu.classList.remove("show");
  });
}